-- NUR AUF RASITS ENTSCHEIDUNG: Der Blindlöser fand weiter einen Taschenrechner-Weg (Probieren; exakte Anzeige). Siehe Prüfliste.
-- LSA-Aufgaben taschenrechnersicher (30.10.2026, vor Batus LSA am 31.10.). Standard: docs/aufgaben/tr-sichere-items.md,
-- Einzelnachweis: docs/aufgaben/tr-umbau-2026-10-30.md.
--
-- Nur Daten, 5 freigegebene LSA-Aufgaben: Aus dem Endwert (NUMERIC) wird ein Lückentext (MULTI_PART, nur Zahlenfelder,
-- weil das Tablet Zahl, Bruch und ax+b kennt, kein √). ID, Skill, Thema, Klasse, AFB, einsatz bleiben.
-- Je Aufgabe nur, wo der Vorher-Stand steht (status ready, NUMERIC, alter Aufgabentext); ein zweiter Lauf und der
-- CI-Neuaufbau (Aufgaben fehlen) treffen 0 Zeilen.
--
-- Status 'review': In Prüfliste und Admin-Reihe „zur Freigabe“. Keine Aufgabe wird hier freigegeben. Vor dem Umbau wird die
-- Ausgangsfassung gesichert, damit die Änderung als „geändert“ erscheint: pruef_freigabe_erlaubt ist dann false, Themen-
-- und Sammelfreigabe lassen die Aufgabe aus, Rasit gibt jede einzeln frei (pruef_admin_freigeben). Der Trigger
-- tasks_hinweise_bei_ruecknahme setzt vorhandene Hinweise auf entwurf; die Freigabe setzt sie wieder auf geprueft.
-- Gate-Prüfung am Ende: Besteht eine Aufgabe freigabe_gate_fehler nicht, bricht die Migration ab.
-- Kein begin/commit: mig klammert. Rollback: supabase/rollback/20261030084256_lsa_tr_sichere_wurzel.sql

do $tr$
declare
  r record;
  v_alt_status text;
  v_n integer;
  v_ges integer := 0;
  v_gate text;
begin
  for r in
    select * from jsonb_to_recordset($alle$[
{"id": "21427340-fc85-41c4-abea-99ad0121b83c", "alt_question": "Es gilt √48 = a · √3.\n\nBestimme a. a ist eine natürliche Zahl. Gib a exakt an.", "question": "Schreibe √48 so um, dass vor der Wurzel eine möglichst große natürliche Zahl steht. Fülle dazu die Lücken aus.\n\n√48 = √(☐ · ☐) = ☐ · √☐", "title": "Teilweise Wurzel ziehen · √48", "est": 90, "parts": [{"nr": 1, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Erster Faktor unter der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}, {"nr": 2, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Zweiter Faktor unter der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}, {"nr": 3, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Zahl vor der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}, {"nr": 4, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Zahl unter der Wurzel am Ende", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}], "correct_answers": {"1": ["16", "+16", "3", "+3"], "2": ["3", "+3", "16", "+16"], "3": ["4", "+4"], "4": ["3", "+3"]}, "acceptance": {"1": {"canonical": "16", "equivalents": ["+16", "3", "+3"]}, "2": {"canonical": "3", "equivalents": ["+3", "16", "+16"]}, "3": {"canonical": "4", "equivalents": ["+4"], "known_errors": {"8": "wurzel_halbiert", "+8": "wurzel_halbiert", "16": "faktor_ohne_wurzel", "+16": "faktor_ohne_wurzel", "6,93": "falsche_groesse_beantwortet", "+6,93": "falsche_groesse_beantwortet"}}, "4": {"canonical": "3", "equivalents": ["+3"]}}, "solution": "48 = 16 · 3, also √48 = √16 · √3 = 4 · √3.", "typical_errors": [{"error": "Den Faktor 16 herausgezogen, ohne aus ihm die Wurzel zu ziehen.", "fehlbild": "faktor_ohne_wurzel", "socratic_question": "Was ergibt (16 · √3)² – ist das 48?"}, {"error": "√16 als 16 : 2 = 8 genommen.", "fehlbild": "wurzel_halbiert", "socratic_question": "Was ergibt 8 · 8?"}, {"error": "Den Näherungswert von √48 angegeben statt der Zahl vor der Wurzel.", "fehlbild": "falsche_groesse_beantwortet", "socratic_question": "Nach welcher Zahl ist gefragt: nach √48 oder nach dem Faktor vor √3?"}]},
