{"id": "0bcc83c8-42f0-4956-b1d0-00446cb6e5e2", "alt_question": "Es gilt √72 = a · √2.\n\nBestimme a. a ist eine natürliche Zahl. Gib a exakt an.", "question": "Schreibe √72 so um, dass vor der Wurzel eine möglichst große natürliche Zahl steht. Fülle dazu die Lücken aus.\n\n√72 = √(☐ · ☐) = ☐ · √☐", "title": "Teilweise Wurzel ziehen · √72", "est": 90, "parts": [{"nr": 1, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Erster Faktor unter der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}, {"nr": 2, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Zweiter Faktor unter der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}, {"nr": 3, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Zahl vor der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}, {"nr": 4, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Zahl unter der Wurzel am Ende", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}], "correct_answers": {"1": ["36", "+36", "2", "+2"], "2": ["2", "+2", "36", "+36"], "3": ["6", "+6"], "4": ["2", "+2"]}, "acceptance": {"1": {"canonical": "36", "equivalents": ["+36", "2", "+2"]}, "2": {"canonical": "2", "equivalents": ["+2", "36", "+36"]}, "3": {"canonical": "6", "equivalents": ["+6"], "known_errors": {"18": "wurzel_halbiert", "+18": "wurzel_halbiert", "36": "faktor_ohne_wurzel", "+36": "faktor_ohne_wurzel", "8,49": "falsche_groesse_beantwortet", "+8,49": "falsche_groesse_beantwortet"}}, "4": {"canonical": "2", "equivalents": ["+2"]}}, "solution": "72 = 36 · 2, also √72 = √36 · √2 = 6 · √2.", "typical_errors": [{"error": "Den Faktor 36 herausgezogen, ohne aus ihm die Wurzel zu ziehen.", "fehlbild": "faktor_ohne_wurzel", "socratic_question": "Was ergibt (36 · √2)² – ist das 72?"}, {"error": "√36 als 36 : 2 = 18 genommen.", "fehlbild": "wurzel_halbiert", "socratic_question": "Was ergibt 18 · 18?"}, {"error": "Den Näherungswert von √72 angegeben statt der Zahl vor der Wurzel.", "fehlbild": "falsche_groesse_beantwortet", "socratic_question": "Nach welcher Zahl ist gefragt: nach √72 oder nach dem Faktor vor √2?"}]},
{"id": "df6b2bcd-8643-46b2-9553-db75854b597d", "alt_question": "Ein quadratischer Spielplatz hat einen Flächeninhalt von 180 m². Seine Seitenlänge lässt sich exakt als a · √5 m schreiben.\n\nBestimme a. a ist eine natürliche Zahl. Gib a exakt an.", "question": "Ein quadratischer Spielplatz hat einen Flächeninhalt von 180 m². Schreibe seine Seitenlänge in m als Wurzel und forme so um, dass vor der Wurzel eine möglichst große natürliche Zahl steht. Fülle dazu die Lücken aus.\n\nSeitenlänge = √☐ = √(☐ · ☐) = ☐ · √☐", "title": "Teilweise Wurzel ziehen · Spielplatz mit 180 m²", "est": 120, "parts": [{"nr": 1, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zahl unter der Wurzel bei der Seitenlänge", "competency_content": "arithmetik_algebra", "competency_process": "Modellieren, Operieren"}, {"nr": 2, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Erster Faktor unter der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Modellieren, Operieren"}, {"nr": 3, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zweiter Faktor unter der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Modellieren, Operieren"}, {"nr": 4, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zahl vor der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Modellieren, Operieren"}, {"nr": 5, "afb": "II", "kind": "short_input", "unit": null, "prompt": "Zahl unter der Wurzel am Ende", "competency_content": "arithmetik_algebra", "competency_process": "Modellieren, Operieren"}], "correct_answers": {"1": ["180", "+180"], "2": ["36", "+36", "5", "+5"], "3": ["5", "+5", "36", "+36"], "4": ["6", "+6"], "5": ["5", "+5"]}, "acceptance": {"1": {"canonical": "180", "equivalents": ["+180"]}, "2": {"canonical": "36", "equivalents": ["+36", "5", "+5"]}, "3": {"canonical": "5", "equivalents": ["+5", "36", "+36"]}, "4": {"canonical": "6", "equivalents": ["+6"], "known_errors": {"18": "wurzel_halbiert", "+18": "wurzel_halbiert", "36": "faktor_ohne_wurzel", "+36": "faktor_ohne_wurzel", "13,42": "falsche_groesse_beantwortet", "+13,42": "falsche_groesse_beantwortet"}}, "5": {"canonical": "5", "equivalents": ["+5"]}}, "solution": "Seitenlänge = √180 m.\n180 = 36 · 5, also √180 = √36 · √5 = 6 · √5.", "typical_errors": [{"error": "Den Faktor 36 herausgezogen, ohne aus ihm die Wurzel zu ziehen.", "fehlbild": "faktor_ohne_wurzel", "socratic_question": "Was ergibt (36 · √5)² – ist das 180?"}, {"error": "√36 als 36 : 2 = 18 genommen.", "fehlbild": "wurzel_halbiert", "socratic_question": "Was ergibt 18 · 18?"}, {"error": "Die Seitenlänge als Näherungswert angegeben statt der Zahl vor der Wurzel.", "fehlbild": "falsche_groesse_beantwortet", "socratic_question": "Nach welcher Zahl ist gefragt: nach der Seitenlänge oder nach dem Faktor vor √5?"}]},
{"id": "1dece473-758d-4108-9969-02b495dbf4ed", "alt_question": "Es gilt √18 · √6 = a · √3.\n\nBestimme a. a ist eine natürliche Zahl. Gib a exakt an.", "question": "Fasse √18 · √6 zusammen und schreibe das Ergebnis so um, dass vor der Wurzel eine möglichst große natürliche Zahl steht. Fülle dazu die Lücken aus.\n\n√18 · √6 = √☐ = √(☐ · ☐) = ☐ · √☐", "title": "Teilweise Wurzel ziehen · √18 · √6", "est": 120, "parts": [{"nr": 1, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Zahl unter der Wurzel nach dem Zusammenfassen", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}, {"nr": 2, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Erster Faktor unter der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}, {"nr": 3, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Zweiter Faktor unter der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}, {"nr": 4, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Zahl vor der Wurzel", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}, {"nr": 5, "afb": "I", "kind": "short_input", "unit": null, "prompt": "Zahl unter der Wurzel am Ende", "competency_content": "arithmetik_algebra", "competency_process": "Operieren"}], "correct_answers": {"1": ["108", "+108"], "2": ["36", "+36", "3", "+3"], "3": ["3", "+3", "36", "+36"], "4": ["6", "+6"], "5": ["3", "+3"]}, "acceptance": {"1": {"canonical": "108", "equivalents": ["+108"]}, "2": {"canonical": "36", "equivalents": ["+36", "3", "+3"]}, "3": {"canonical": "3", "equivalents": ["+3", "36", "+36"]}, "4": {"canonical": "6", "equivalents": ["+6"], "known_errors": {"18": "wurzel_halbiert", "+18": "wurzel_halbiert", "36": "faktor_ohne_wurzel", "+36": "faktor_ohne_wurzel", "10,39": "falsche_groesse_beantwortet", "+10,39": "falsche_groesse_beantwortet"}}, "5": {"canonical": "3", "equivalents": ["+3"]}}, "solution": "√18 · √6 = √108.\n108 = 36 · 3, also √108 = √36 · √3 = 6 · √3.", "typical_errors": [{"error": "Den Faktor 36 herausgezogen, ohne aus ihm die Wurzel zu ziehen.", "fehlbild": "faktor_ohne_wurzel", "socratic_question": "Was ergibt (36 · √3)² – ist das 108?"}, {"error": "√36 als 36 : 2 = 18 genommen.", "fehlbild": "wurzel_halbiert", "socratic_question": "Was ergibt 18 · 18?"}, {"error": "Den Näherungswert von √108 angegeben statt der Zahl vor der Wurzel.", "fehlbild": "falsche_groesse_beantwortet", "socratic_question": "Nach welcher Zahl ist gefragt: nach dem Produkt oder nach dem Faktor vor √3?"}]}
]$alle$::jsonb) as x(id uuid, alt_question text, question text, title text, est integer, parts jsonb,
                     correct_answers jsonb, acceptance jsonb, solution text, typical_errors jsonb)
  loop
    if not exists (select 1 from public.tasks t where t.id = r.id and t.status = 'ready' and t.input_type = 'NUMERIC'
                      and t.question = r.alt_question) then
      raise notice 'tr: % nicht im Vorher-Stand, übersprungen', r.id;
      continue;
    end if;
    perform public.pruef_ausgang_sichern(r.id);
    update public.tasks
       set question = r.question, question_payload = null, input_type = 'MULTI_PART', parts = r.parts,
           title = r.title, est_duration_sec = r.est, status = 'review', reviewed_by = null, reviewed_at = null
     where id = r.id and status = 'ready';
    get diagnostics v_n = row_count;
    update public.task_solutions
       set correct_answers = r.correct_answers, acceptance = r.acceptance, solution = r.solution,
           typical_errors = r.typical_errors, updated_at = now()
     where task_id = r.id;
    v_ges := v_ges + v_n;
    v_gate := public.freigabe_gate_fehler(r.id);
    if v_gate is not null then
      raise exception 'tr: % besteht das Gate nicht: %', r.id, v_gate;
    end if;
  end loop;
  raise notice 'tr: % Aufgabe(n) umgebaut', v_ges;
end
$tr$;
